using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace SecureProxy
{
    public sealed class TenantKeyManager
    {
        private readonly ConcurrentDictionary<string, byte[]> _tenantKeys = new();
        private readonly byte[] _masterSeed;
        private int _derivationCounter;

        public TenantKeyManager(byte[] masterSeed)
        {
            _masterSeed = masterSeed ?? throw new ArgumentNullException(nameof(masterSeed));
            _derivationCounter = 0;
        }

        public byte[] GetOrCreateKey(string tenantId)
        {
            return _tenantKeys.GetOrAdd(tenantId, id => DeriveKeyForTenant(id));
        }

        private byte[] DeriveKeyForTenant(string tenantId)
        {
            int counter = Interlocked.Increment(ref _derivationCounter);
            using var hmac = new HMACSHA256(_masterSeed);
            byte[] context = Encoding.UTF8.GetBytes($"{tenantId}:{counter}");
            byte[] derived = hmac.ComputeHash(context);
            return derived;
        }
    }

    public sealed class SessionCipher : IDisposable
    {
        private readonly byte[] _key;
        private long _sequenceNumber;

        public SessionCipher(byte[] key)
        {
            _key = (byte[])key.Clone();
            _sequenceNumber = 0;
        }

        public byte[] Encrypt(byte[] plaintext)
        {
            long seq = Interlocked.Increment(ref _sequenceNumber);
            byte[] nonce = ComputeNonce(seq);
            using var aes = new AesGcm(_key);
            byte[] ciphertext = new byte[plaintext.Length];
            byte[] tag = new byte[16];
            aes.Encrypt(nonce, plaintext, ciphertext, tag);
            byte[] result = new byte[8 + 12 + ciphertext.Length + 16];
            BitConverter.GetBytes(seq).CopyTo(result, 0);
            nonce.CopyTo(result, 8);
            ciphertext.CopyTo(result, 20);
            tag.CopyTo(result, 20 + ciphertext.Length);
            return result;
        }

        public byte[] Decrypt(byte[] packet)
        {
            if (packet == null) throw new ArgumentNullException(nameof(packet));
            // Minimum packet size: 8 (seq) + 12 (nonce) + 16 (tag) = 36 bytes.
            if (packet.Length < 36)
                throw new ArgumentException("Packet too short to contain header, nonce and authentication tag.", nameof(packet));

            long seq = BitConverter.ToInt64(packet, 0);
            byte[] nonce = new byte[12];
            Array.Copy(packet, 8, nonce, 0, 12);
            byte[] ciphertext = new byte[packet.Length - 36];
            Array.Copy(packet, 20, ciphertext, 0, ciphertext.Length);
            byte[] tag = new byte[16];
            Array.Copy(packet, packet.Length - 16, tag, 0, 16);
            using var aes = new AesGcm(_key);
            byte[] plaintext = new byte[ciphertext.Length];
            aes.Decrypt(nonce, ciphertext, tag, plaintext);
            return plaintext;
        }

        private byte[] ComputeNonce(long sequenceNumber)
        {
            byte[] nonce = new byte[12];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(nonce, 0, 4);
            }
            byte[] seqBytes = BitConverter.GetBytes(sequenceNumber);
            for (int i = 0; i < 8; i++)
            {
                nonce[i + 4] ^= seqBytes[i];
            }
            return nonce;
        }

        public void Dispose()
        {
            Array.Clear(_key, 0, _key.Length);
        }
    }

    public sealed class MultiTenantProxy
    {
        private readonly TenantKeyManager _keyManager;
        private readonly ConcurrentDictionary<string, SessionCipher> _sessions = new();
        private readonly TcpListener _listener;

        public MultiTenantProxy(IPAddress bindAddress, int port, byte[] masterSeed)
        {
            _keyManager = new TenantKeyManager(masterSeed);
            _listener = new TcpListener(bindAddress, port);
        }

        public async Task StartAsync(CancellationToken ct)
        {
            _listener.Start();
            while (!ct.IsCancellationRequested)
            {
                var client = await _listener.AcceptTcpClientAsync();
                _ = Task.Run(() => HandleClientAsync(client, ct), ct);
            }
        }

        private async Task HandleClientAsync(TcpClient client, CancellationToken ct)
        {
            using (client)
            using (var stream = client.GetStream())
            {
                byte[] header = new byte[256];
                int read = await stream.ReadAsync(header, 0, header.Length, ct);
                string tenantId = ExtractTenantId(header, read);
                if (string.IsNullOrEmpty(tenantId)) return;

                var cipher = GetOrCreateSession(tenantId);
                await ProxyTrafficAsync(stream, cipher, ct);
            }
        }

        private SessionCipher GetOrCreateSession(string tenantId)
        {
            return _sessions.GetOrAdd(tenantId, id =>
            {
                byte[] key = _keyManager.GetOrCreateKey(id);
                return new SessionCipher(key);
            });
        }

        private string ExtractTenantId(byte[] header, int length)
        {
            string raw = Encoding.UTF8.GetString(header, 0, length);
            string[] parts = raw.Split('\n');
            foreach (var line in parts)
            {
                if (line.StartsWith("X-Tenant-Id:", StringComparison.OrdinalIgnoreCase))
                {
                    return line.Substring(12).Trim();
                }
            }
            return null;
        }

        private async Task ProxyTrafficAsync(NetworkStream stream, SessionCipher cipher, CancellationToken ct)
        {
            byte[] buffer = new byte[4096];
            while (!ct.IsCancellationRequested)
            {
                int bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length, ct);
                if (bytesRead == 0) break;
                byte[] data = new byte[bytesRead];
                Array.Copy(buffer, data, bytesRead);
                byte[] encrypted = cipher.Encrypt(data);
                byte[] lengthPrefix = BitConverter.GetBytes(encrypted.Length);
                await stream.WriteAsync(lengthPrefix, 0, 4, ct);
                await stream.WriteAsync(encrypted, 0, encrypted.Length, ct);
            }
        }
    }
}
